<script>
export let data;
import FixtureMenu from './FixtureMenu.svelte';
import {importBusy,acceptImportUpdate,matchesImport} from './import-state.mjs';
import {environments,environmentLabel} from './environments.mjs';
import Icon from './Icon.svelte';
import FixtureImport from './FixtureImport.svelte';
let fixtureMode=data.job?.progress?.verification?'import':'create',importJob=data.job?.progress?.verification?data.job:null,importPending=false;
function imported(value){if(!matchesImport(value,profileId))return;importJob=value;busyJob=value;watch(value,'import');}
async function cancelImport(value){try{const result=await api.cancel(value.id);if(value.id===importJob?.id)importJob=result;busyJob=result;}catch(e){error=e.message;}}
import ConnectorCredentials from './ConnectorCredentials.svelte';
import {defaultConnectorPlan,connectorSet} from './connector-config.mjs';
let connectorCredentials={},credentialProfile='';
$: if(profileId!==credentialProfile){credentialProfile=profileId;connectorCredentials={};}
import {setQuery} from './navigation.mjs';import ConnectionStatus from './ConnectionStatus.svelte';import {watchJobStream} from './job-stream.mjs';
import {fixtureSteps} from './fixture-steps.mjs';
import {onMount} from 'svelte';import {api} from './api.js';import FollowingLog from './FollowingLog.svelte';
let pendingDelete=null,deleting=false;
let settings=data.settings,profiles=data.profiles,profileId=data.profileId || profiles[0]?.id,sets=data.fixtures,job=data.job?.command==='fixtures'?data.job:null,busyJob=data.job,pending=false,error='',events,connection='connecting',updatedAt=0;
$: providerSupported=environments.find(e=>e.id===(settings?.environment||'local'))?.supported;
$: steps=fixtureSteps(job);
$: repairable=sets.some(set=>set.repairable&&set.mode===profile?.mode&&set.merchant_count===profile?.merchantCount);
$: profile=profiles.find(p=>p.id===profileId);
let importContext='';
$: {const context=JSON.stringify([profileId,profile?.version,settings]);if(importContext&&importContext!==context){importJob=null;}importContext=context;}
$: active=['starting','running','pausing','paused','cancelling'].includes(busyJob?.status) && busyJob?.command!=='reconcile';
async function start(){pending=true;error='';try{const credentials=Object.fromEntries(Object.entries(connectorCredentials).map(([id,row])=>[id,{credentials:row.credentials,metadata:row.metadataText?JSON.parse(row.metadataText):{}}]));job=await api.start('fixtures',{mode:profile.mode,profileId:profile.id,version:profile.version,connectorCredentials:credentials});connectorCredentials={};busyJob=job;sets=await api.fixtures();watch();}catch(e){error=e.message;}finally{pending=false;}}
let observation=0;
function watch(value=job,destination='create'){events?.close();const generation=++observation,id=value.id;events=watchJobStream(id,async next=>{if(generation!==observation||next.id!==id)return;
if(destination==='import'){if(!acceptImportUpdate(importJob,next,profileId))return;importJob=next;}else job=next;
busyJob=next;if(!importBusy(next)){events?.close();sets=await api.fixtures();if(destination==='create'&&next.error)error=next.error;}},(state,at)=>{connection=state;updatedAt=at;});}

async function removeFixtures(){if(deleting||!pendingDelete)return;deleting=true;error='';try{await api.deleteFixtures(pendingDelete.id);sets=await api.fixtures();pendingDelete=null;}catch(e){error=e.message;}finally{deleting=false;}}
async function stop(){try{job=await api.cancel(job.id);busyJob=job;}catch(e){error=e.message;}}
onMount(()=>{const connections=async()=>{try{[sets,settings]=await Promise.all([api.fixtures(),api.settings()]);error='';}catch(e){error=e.message;}};window.addEventListener('console-connections-saved',connections);if(importJob&&active)watch(importJob,'import');else if(job&&active)watch();const poll=setInterval(async()=>{try{const r=await fetch('/api/jobs');if(r.ok){busyJob=await r.json();if(busyJob?.progress?.verification&&busyJob.id!==importJob?.id){profileId=busyJob.progress.verification.profileId||profileId;fixtureMode='import';imported(busyJob);}else if(busyJob?.command==='fixtures'&&!busyJob.progress?.verification&&busyJob.id!==job?.id){job=busyJob;watch();}}}catch{}},3000);return()=>{events?.close();clearInterval(poll);window.removeEventListener('console-connections-saved',connections);};});
</script>
<svelte:head><title>Fixtures · Testbench</title></svelte:head>
<main><div class="section-head"><div><h1>Fixtures</h1><p>Prepare the merchants and connections your scenarios need.</p></div><button class="secondary" onclick={()=>window.dispatchEvent(new Event('console-settings'))}>Connection settings</button></div>{#if error}<div class="message error" role="alert">{error}</div>{/if}
<section class="fixture-setup surface"><label>Fixture source<select bind:value={fixtureMode} disabled={pending||importPending||active}><option value="create">Create new</option><option value="import">Import existing</option></select></label>{#if !providerSupported}<p role="status">{environmentLabel(settings.environment)} execution is not available. Select Local or GCP in Settings.</p>{/if}<div class="load-controls"><label>Scenario<select disabled={pending||importPending||active} bind:value={profileId} onchange={()=>setQuery({profile:profileId})}>{#each profiles as p}<option value={p.id}>{p.name} · {p.mode==='tenancy'?'Tenancy':'Single'} · v{p.version}</option>{/each}</select></label><div class="fixture-summary"><strong>{profile?.mode==='tenancy'?'Tenancy':'Single'} · {profile?.merchantCount} {profile?.merchantCount===1?'merchant':'merchants'}</strong><p>{fixtureMode==='import'?'Verification uses the Router and PM connections in Settings.':'Provisioning uses the connections and Superposition defaults in Settings.'}</p></div></div>{#if fixtureMode==='create'}<div class="actions"><button disabled={pending||active||!profile||!providerSupported} onclick={start}>{pending?'Starting…':active?'Job in progress':repairable?'Repair fixtures':'Create fixtures'}</button></div><ConnectorCredentials plan={profile?.connectors||defaultConnectorPlan()} bind:value={connectorCredentials}/>{:else}{#key `${profileId}:${profile?.version}:${settings.environment}:${settings.routerBaseUrl}:${settings.pmBaseUrl}`}<FixtureImport {profile} job={importJob} disabled={pending||active||!providerSupported} onstart={imported} onreset={()=>importJob=null} onbusy={value=>importPending=value} oncancel={()=>cancelImport(importJob)}/>{/key}{/if}{#if (active&&!busyJob.progress?.verification)||repairable}<p class="muted">{active?`${busyJob.command} · ${busyJob.status}`:'Resumes the interrupted fixture set and reuses existing merchants.'}</p>{/if}{#if active&&busyJob.command!=='fixtures'&&!busyJob.progress?.verification}<a class="quiet" href="/performance">View active job →</a>{/if}</section>
{#if job&&!job.progress?.verification}<section class="activity"><div class="section-head"><div><h2>Fixture setup · {job.status}</h2>{#if active}<ConnectionStatus state={connection} {updatedAt}/>{/if}</div>{#if active}<button class="secondary danger" onclick={stop}>Stop</button>{/if}</div><p role="status">{job.progress?.fixtures?.completed ?? 0} / {job.progress?.fixtures?.total ?? profile?.merchantCount} merchants provisioned</p><progress aria-label="Fixture provisioning progress" value={job.status==='complete'?(job.progress?.fixtures?.total ?? profile?.merchantCount):(job.progress?.fixtures?.completed ?? 0)} max={job.progress?.fixtures?.total ?? profile?.merchantCount}></progress><div class="setup-steps" aria-label="Fixture setup steps">{#each steps as step,i}<div class="setup-step" class:running={step.status==='running'} class:complete={step.status==='complete'}><span class="step-number">{#if step.status==='complete'}<Icon name="check"/>{:else}{i+1}{/if}</span><div><strong>{step.label}</strong><span>{step.status==='running'?'In progress':step.status==='complete'?'Complete':step.status==='failed'?'Failed':step.status==='skipped'?'Skipped':'Pending'}</span></div>{#if step.detail}<p role="status">{step.detail}</p>{/if}{#if step.label==='Service refresh'&&step.status==='running'&&step.total>0}<progress aria-label="Superposition service refresh progress" value={step.total-step.remaining} max={step.total}></progress>{/if}</div>{/each}</div><details class="fixture-events"><summary>Activity · {job.events?.length || 0} events</summary><ol>{#each job.events || [] as event}<li><time>{new Date(event.at).toLocaleTimeString()}</time><span>{event.message}</span></li>{/each}</ol></details><details class="diagnostics"><summary>Provisioning output</summary><FollowingLog output={job.output || ''} label="Provisioning output"/></details></section>{/if}
<section class="fixture-list"><div class="section-head panels-head"><h2>Fixture sets</h2></div><div class="table-wrap fixture-sets surface"><table><thead><tr><th>Set</th><th>Source</th><th>Mode</th><th>Merchants</th><th>Status</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>{#each sets as set}<tr><td><strong>{set.id.slice(0,8)}</strong><small class="fixture-meta">{new Date(set.created_at).toLocaleString()}</small><small class="fixture-meta">{set.destination}</small></td><td><span class="source-tag" class:imported={set.source==='imported'}>{set.source==='imported'?'Imported':'Created'}</span></td><td>{set.mode==='tenancy'?'Tenancy':'Single'}</td><td>{set.merchant_count}</td><td>{set.source==='imported'?(!set.compatible?'Verification required':'Ready'):!set.compatible?'Needs refresh':set.status==='ready'?'Ready':set.status==='creating'?'Preparing':set.status==='interrupted'?'Interrupted':set.status==='failed'?'Failed':set.status}{#if !set.compatible}<small class="fixture-meta">{set.source==='imported'?'Import again to verify current connections.':'Provisioning settings changed.'}</small>{/if}</td><td><FixtureMenu id={set.id} href={set.status==='ready'&&set.compatible&&set.mode===profile?.mode&&set.merchant_count===profile?.merchantCount&&JSON.stringify(set.connectors||['stripe_test'])===JSON.stringify(connectorSet(profile?.connectors))?`/performance?profile=${profileId}&fixtures=${set.id}`:''} disabled={active||pending||deleting} deleting={deleting&&pendingDelete?.id===set.id} ondelete={()=>{pendingDelete=set;removeFixtures();}}/></td></tr>{/each}</tbody></table>{#if !sets.length}<p class="muted">No fixtures yet. Create or import one above.</p>{/if}</div></section></main>


<style>


 .fixture-list{max-width:1000px}.source-tag{display:inline-block;padding:4px 7px;border-radius:4px;background:var(--hover-bg);color:var(--muted);font-size:11px}.source-tag.imported{background:var(--accent-soft);color:var(--accent)}.fixture-sets th:last-child,.fixture-sets td:last-child{width:48px;padding-right:12px}.fixture-sets td:first-child{max-width:270px}.fixture-sets td:nth-child(5){max-width:200px}
.fixture-setup{padding:20px;margin-bottom:24px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px 24px;align-items:center}.fixture-setup .load-controls{border:0;padding:0;margin:0;gap:24px}.fixture-setup>.actions{margin:0;align-self:end}.fixture-setup>p{grid-column:1/-1;margin:0;font-size:11px}.fixture-summary p{max-width:340px}.fixture-meta{display:block;font-size:11px;color:var(--muted);margin-top:5px;overflow-wrap:anywhere}.fixture-sets{padding:0}.fixture-sets>p{padding:20px}.setup-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:24px 0;gap:20px}.setup-step{display:grid;grid-template-columns:26px 1fr;gap:8px;border-top:2px solid var(--border);padding-top:14px;align-content:start}.setup-step.running{border-color:var(--accent)}.setup-step.complete{border-color:var(--success)}.setup-step>div{display:flex;flex-direction:column;gap:5px}.setup-step strong{font-size:12px;font-weight:550}.setup-step span,.setup-step p{font-size:11px;color:var(--muted)}.setup-step .step-number{display:flex;align-items:center;justify-content:center;width:24px;height:24px;border-radius:50%;background:#eef1f6;color:var(--muted);font-size:11px}.setup-step.running .step-number{background:var(--accent-soft);color:var(--accent)}.setup-step.complete .step-number{background:var(--success-soft);color:var(--success)}.setup-step p{grid-column:2;margin:0;line-height:1.4}.setup-step.complete>div>span{color:var(--success)}.setup-step progress{grid-column:2;margin:4px 0 0}.fixture-events{padding-top:16px;border-top:1px solid var(--border)}.fixture-events ol{margin-top:14px}.activity>.section-head{margin-bottom:16px}.activity>.section-head h2{margin:0}.activity>p{font-size:12px;margin:0}.activity>.diagnostics{border:0;border-top:1px solid var(--border);border-radius:0;padding:16px 0 0}
@media(max-width:1000px){.fixture-setup{grid-template-columns:1fr}.fixture-setup>.actions{justify-self:end}}@media(max-width:650px){.fixture-setup{padding:16px}.setup-steps{grid-template-columns:1fr 1fr;gap:18px 12px}.fixture-setup .load-controls{grid-template-columns:1fr}.fixture-setup>.actions{justify-self:stretch}.fixture-setup>.actions>button{width:100%}}
</style>
